// RP2040 core-local NVIC registers and one-shot software pending semantics.
// The engine otherwise treats every numbered peripheral IRQ as a permanent level.
export class PicoNVIC {
 constructor(runtime){this.r=runtime;this.old=runtime.board.mcu==='RP2040';this.lines=[0,0];if(!this.old)return;runtime.rp.core.forEach((core,index)=>{core.setInterrupt=(irq,value)=>{const bit=1<<irq;this.lines[index]=value?this.lines[index]|bit:this.lines[index]&~bit;if(value)core.pendingInterrupts|=bit;core.interruptsUpdated=true;};const entry=core.exceptionEntry.bind(core);core.exceptionEntry=n=>{if(n>=16&&n<48)core.pendingInterrupts&=~(1<<(n-16));entry(n);};const leave=core.exceptionReturn.bind(core);core.exceptionReturn=n=>{leave(n);core.pendingInterrupts|=this.lines[index];core.interruptsUpdated=true;};});}
 read(address){if(!this.old){const a=address>>>0;if(a<0xe000e400||a>0xe000e430||(a&3))return null;const st=this.r.rp.ppb.coreState[this.r.rp.currentCore||0];let value=0;for(let i=0;i<4;i++)value|=st.nvicPriority[a-0xe000e400+i]<<(i*8+4);return value>>>0;}const c=this.r.rp.core[this.r.rp.currentCore||0],a=address>>>0;if(a===0xe000ed08)return c.VTOR>>>0;if(a===0xe000e100||a===0xe000e180)return c.enabledInterrupts>>>0;if(a===0xe000e200||a===0xe000e280)return c.pendingInterrupts>>>0;if(a>=0xe000e400&&a<=0xe000e41c&&!(a&3)){let v=0;const first=a-0xe000e400;for(let b=0;b<4;b++)for(let p=0;p<4;p++)if(c.interruptPriorities[p]&(1<<(first+b)))v|=p<<(b*8+6);return v>>>0;}return null;}
 write(address,value){if(this.read(address)===null)return false;if(!this.old){const id=this.r.rp.currentCore||0,st=this.r.rp.ppb.coreState[id];for(let i=0;i<4;i++)st.nvicPriority[(address>>>0)-0xe000e400+i]=(value>>>(i*8+4))&15;this.r.rp.core[id].interruptsUpdated=true;return true;}const c=this.r.rp.core[this.r.rp.currentCore||0],a=address>>>0;if(a===0xe000ed08)c.VTOR=value&~255;else if(a===0xe000e100)c.enabledInterrupts|=value;else if(a===0xe000e180)c.enabledInterrupts&=~value;else if(a===0xe000e200)c.pendingInterrupts|=value;else if(a===0xe000e280)c.pendingInterrupts=(c.pendingInterrupts&~value)|this.lines[this.r.rp.currentCore||0];else{const first=a-0xe000e400;for(let b=0;b<4;b++){const bit=1<<(first+b),p=value>>>(b*8+6)&3;for(let n=0;n<4;n++)c.interruptPriorities[n]&=~bit;c.interruptPriorities[p]|=bit;}}c.interruptsUpdated=true;return true;}
}
